/* Read-only tinnitus availability: read the active program icon before any tab search. */
import android.accessibilityservice.AccessibilityServiceInfo;
import android.view.accessibility.AccessibilityNodeInfo;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
tasker.setVariable("SIG3_TinnitusAvailable", "0");
try {
    service = tasker.getAccessibilityService();
    if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
    root = service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
        throw new JavaCodeException("Signia is not foreground");
    queue = new java.util.ArrayList(); queue.add(root);
    programIcon = "";
    tasker.setVariable("SIG3_ProgramIcon", "");
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        description = node.getContentDescription();
        if (node.isVisibleToUser() && node.isEnabled() && description != null
            && description.toString().startsWith("Hearing program ")
            && description.toString().endsWith(" Active")) {
            headerNodes = new java.util.ArrayList(); headerNodes.add(node);
            for (h = 0; h < headerNodes.size() && h < 30; h++) {
                headerNode = (AccessibilityNodeInfo) headerNodes.get(h);
                iconText = headerNode.getText();
                if (headerNode.isVisibleToUser() && iconText != null
                    && ("\uE912".contentEquals(iconText) || "\uE909".contentEquals(iconText)))
                    {
                        programIcon = iconText.toString();
                        tasker.setVariable("SIG3_ProgramIcon", programIcon);
                        if ("\uE909".equals(programIcon)) {
                            tasker.setVariable("SIG3_Error", "Tinnitus unavailable for this program");
                            return "unavailable";
                        }
                        tasker.setVariable("SIG3_TinnitusAvailable", "1");
                        return "available";
                    }
                for (hc = 0; hc < headerNode.getChildCount() && headerNodes.size() < 30; hc++) {
                    headerChild = headerNode.getChild(hc);
                    if (headerChild != null) headerNodes.add(headerChild);
                }
            }
        }
        for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
            child = node.getChild(childIndex);
            if (child != null) queue.add(child);
        }
    }
    tasker.setVariable("SIG3_ProgramIcon", programIcon);
    // Only an unknown icon needs a fallback search for the actual tinnitus tab.
    queue = new java.util.ArrayList(); queue.add(root); tabs = 0;
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        description = node.getContentDescription();
        if (node.isVisibleToUser() && node.isEnabled() && description != null
            && ("Tinnitus Signal Tab".contentEquals(description) || "Selected Tinnitus Signal Tab".contentEquals(description))) tabs++;
        for (childIndex = 0; childIndex < node.getChildCount() && queue.size() < 300; childIndex++) {
            child = node.getChild(childIndex);
            if (child != null) queue.add(child);
        }
    }
    if (tabs == 1) {
        tasker.setVariable("SIG3_TinnitusAvailable", "1");
        return "available";
    }
    tasker.setVariable("SIG3_Error", "Tinnitus unavailable for this program");
    return "unavailable";
} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Tasker 6.6.20 Java Code (BeanShell). No root, ADB or helper app. */
import android.accessibilityservice.AccessibilityService;
import android.accessibilityservice.GestureDescription;
import android.graphics.Path;
import android.os.Build;
import android.os.Handler;
import android.os.Looper;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicReference;
import com.joaomgcd.taskerm.action.java.ClassImplementation;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

/* Wait for Android's actual completion/cancellation, not merely acceptance. */
performTabDoubleTap(service, stroke, stroke2, phase) {
    signal = new CountDownLatch(1);
    result = new AtomicReference("timeout");
    callback = tasker.implementClass(AccessibilityService.GestureResultCallback.class,
        new ClassImplementation() {
            run(Callable superCaller, String methodName, Object[] args) {
                if (methodName.equals("onCompleted")) {
                    result.set("completed");
                    signal.countDown();
                    return null;
                }
                if (methodName.equals("onCancelled")) {
                    result.set("cancelled");
                    signal.countDown();
                    return null;
                }
                return superCaller.call();
            }
        });
    tasker.setVariable("SIG3_TouchStage", phase);
    gesture = new GestureDescription.Builder().addStroke(stroke).addStroke(stroke2).build();
    if (!service.dispatchGesture(gesture, callback, new Handler(Looper.getMainLooper())))
        throw new JavaCodeException(phase + ": dispatchGesture rejected");
    if (!signal.await(3, TimeUnit.SECONDS))
        throw new JavaCodeException(phase + ": completion timed out after 3000 ms");
    if (!result.get().equals("completed"))
        throw new JavaCodeException(phase + ": Android cancelled gesture");
}

/* Resolve live tab bounds and activate with a double tap. */
/* Select the actual requested tab before querying its numeric label. */
import android.view.accessibility.AccessibilityNodeInfo;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
    family = tasker.getVariable("SIG3_Family");
    if (!"Volume".equals(family) && !"Balance".equals(family) && !"Tinnitus".equals(family))
        throw new JavaCodeException("Unknown slider family");
    tabDescription = "Balance".equals(family) ? "Sound Sharpness Tab"
        : "Tinnitus".equals(family) ? "Tinnitus Signal Tab" : "Volume Tab";
    service = tasker.getAccessibilityService();
    root = service == null ? null : service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
        throw new JavaCodeException("Signia is not foreground");
    queue = new java.util.ArrayList(); queue.add(root);
    tab = null; count = 0; selected = false;
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        description = node.getContentDescription();
        if (node.isVisibleToUser() && node.isEnabled() && description != null
            && (tabDescription.contentEquals(description) || ("Selected " + tabDescription).contentEquals(description))) {
            tab = node; count++; selected = ("Selected " + tabDescription).contentEquals(description);
        }
        for (i = 0; i < node.getChildCount() && queue.size() < 300; i++) {
            child = node.getChild(i); if (child != null) queue.add(child);
        }
    }
    if (count != 1) throw new JavaCodeException("Expected exactly one enabled " + family + " tab");
    tasker.setVariable("sig3_tab_selected", selected ? "1" : "0");
    if (selected) return "already selected";
    if (Build.VERSION.SDK_INT < 24) throw new JavaCodeException("Tab double tap requires Android 7 or later");
    // A program header can change before Signia accepts tab touches.
    // Re-read the tab after settling so a changed layout cannot leave stale X/Y.
    java.lang.Thread.sleep(3000);
    root = service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
        throw new JavaCodeException("Signia is not foreground");
    queue = new java.util.ArrayList(); queue.add(root);
    tab = null; count = 0; selected = false;
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        node = (AccessibilityNodeInfo) queue.get(scan);
        description = node.getContentDescription();
        if (node.isVisibleToUser() && node.isEnabled() && description != null
            && (tabDescription.contentEquals(description) || ("Selected " + tabDescription).contentEquals(description))) {
            tab = node; count++; selected = ("Selected " + tabDescription).contentEquals(description);
        }
        for (i = 0; i < node.getChildCount() && queue.size() < 300; i++) {
            child = node.getChild(i); if (child != null) queue.add(child);
        }
    }
    if (count != 1) throw new JavaCodeException("Expected exactly one enabled " + family + " tab");
    if (selected) return "selected while settling";
    rect = new android.graphics.Rect(); tab.getBoundsInScreen(rect);
    metrics = service.getResources().getDisplayMetrics();
    x = rect.centerX(); y = rect.centerY();
    if (rect.isEmpty() || rect.left < 0 || rect.top < 0
        || rect.right > metrics.widthPixels || rect.bottom > metrics.heightPixels)
        throw new JavaCodeException("Tab bounds are outside the display");
    tasker.setVariable("sig3_tab_x", "" + x);
    tasker.setVariable("sig3_tab_y", "" + y);
    tasker.setVariable("SIG3_Gesture", family + " tab double tap at " + x + "," + y + "; bounds=" + rect);
    path = new Path(); path.moveTo(x, y);
    performTabDoubleTap(service, new GestureDescription.StrokeDescription(path, 0, 50),
        new GestureDescription.StrokeDescription(path, 150, 50), "tab-double-tap");
    tasker.setVariable("SIG3_TouchStage", "released");
    return "tab double tap completed; selection verification follows";
} catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

import android.view.accessibility.AccessibilityNodeInfo;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
try {
    family = tasker.getVariable("SIG3_Family");
    tabDescription = "Balance".equals(family) ? "Sound Sharpness Tab"
        : "Tinnitus".equals(family) ? "Tinnitus Signal Tab" : "Volume Tab";
    service = tasker.getAccessibilityService();
    // Read the actual selected tab after the coordinate click.
    for (attempt = 0; attempt < 30; attempt++) {
        java.lang.Thread.sleep(100);
        root = service.getRootInActiveWindow();
        if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
            throw new JavaCodeException("Signia left foreground during tab selection");
        queue = new java.util.ArrayList(); queue.add(root); selectedCount = 0;
        for (scan = 0; scan < queue.size() && scan < 300; scan++) {
            node = (AccessibilityNodeInfo) queue.get(scan);
            description = node.getContentDescription();
            if (node.isVisibleToUser() && node.isEnabled() && description != null
                && ("Selected " + tabDescription).contentEquals(description)) selectedCount++;
            for (i = 0; i < node.getChildCount() && queue.size() < 300; i++) {
                child = node.getChild(i); if (child != null) queue.add(child);
            }
        }
        if (selectedCount == 1) return "tab selection verified; slider readback follows";
        if (selectedCount > 1) throw new JavaCodeException("Selected tab is ambiguous");
    }
    throw new JavaCodeException(family + " tab tap completed without verified selection");
 } catch (Exception failure) {
    tasker.setVariable("SIG3_Error", failure.toString());
    throw failure;
}

/* Direct numeric slider action: no simulated touch and no automatic touch fallback. */
import android.view.accessibility.AccessibilityNodeInfo;
import android.view.accessibility.AccessibilityManager;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.os.Bundle;
import android.graphics.Rect;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
service = tasker.getAccessibilityService();
if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
serviceInfo = service.getServiceInfo();
if (serviceInfo == null) throw new JavaCodeException("Tasker accessibility service information unavailable");
serviceInfo.flags = serviceInfo.flags | AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;
service.setServiceInfo(serviceInfo);
root = service.getRootInActiveWindow();
if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName()))
    throw new JavaCodeException("Signia is not foreground");
family = tasker.getVariable("SIG3_Family");
id = tasker.getVariable("SIG3_" + family + "ControlId");
if (id == null) throw new JavaCodeException("Configure the slider control ID");
// Save a read-only tree capture even when the configured selector fails.
inspect = "Inspect".equals(tasker.getVariable("sig3_slider_mode"));
matches = root.findAccessibilityNodeInfosByViewId(id);
lookupCount = matches.size();
visibleCount = 0;
enabledCount = 0;
node = null;
for (candidate : matches) {
    if (candidate.isVisibleToUser()) visibleCount++;
    if (candidate.isEnabled()) enabledCount++;
    if (!candidate.isVisibleToUser() || !candidate.isEnabled()) continue;
    if (node == null) node = candidate;
    else throw new JavaCodeException("Slider ID is ambiguous");
}
lookupDiagnostic = "family=" + family + "; requestedId=" + id + "; matches=" + lookupCount
    + "; visible=" + visibleCount + "; enabled=" + enabledCount
    + "; serviceFlags=" + serviceInfo.flags;
if (inspect || node == null) {
    queue = new java.util.ArrayList();
    queue.add(root);
    capture = lookupDiagnostic;
    treeMatches = 0;
    treeEligible = 0;
    for (scan = 0; scan < queue.size() && scan < 300; scan++) {
        item = (AccessibilityNodeInfo) queue.get(scan);
        itemId = item.getViewIdResourceName();
        itemRange = item.getRangeInfo();
        if (id.equals(itemId)) {
            treeMatches++;
            if (lookupCount == 0 && item.isVisibleToUser() && item.isEnabled()) {
                treeEligible++;
                if (treeEligible == 1) node = item;
            }
        }
        if (itemRange != null || (itemId != null && itemId.toLowerCase().contains("slider"))) {
            itemRect = new Rect(); item.getBoundsInScreen(itemRect);
            capture = capture + "\n" + itemId + " | " + item.getClassName()
                + " | visible=" + item.isVisibleToUser() + " enabled=" + item.isEnabled()
                + " | " + itemRect;
            if (itemRange != null) capture = capture + " | min=" + itemRange.getMin()
                + " max=" + itemRange.getMax() + " current=" + itemRange.getCurrent();
        }
        for (childIndex = 0; childIndex < item.getChildCount() && queue.size() < 300; childIndex++) {
            child = item.getChild(childIndex);
            if (child != null) queue.add(child);
        }
    }
    lookupDiagnostic = lookupDiagnostic + "; treeMatches=" + treeMatches;
    tasker.setVariable("SIG3_QueryData", capture + "\ntreeMatches=" + treeMatches);
    if (treeEligible > 1) throw new JavaCodeException("Slider ID is ambiguous in screen tree: " + id);
    if (lookupCount == 0 && node != null) lookupDiagnostic = lookupDiagnostic + "; lookup=exact-tree-id";
}
tasker.setVariable("SIG3_SliderDiagnostics", lookupDiagnostic);
if (node == null) throw new JavaCodeException("Slider lookup failed: " + lookupDiagnostic + "; see SIG3_QueryData");
manager = context.getSystemService("accessibility");
range = node.getRangeInfo();
actions = "";
canSet = false;
for (entry : node.getActionList()) {
    actions = actions + entry.getId() + ":" + entry.getLabel() + ";";
    if (entry.getId() == AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId()) canSet = true;
}
rect = new Rect(); node.getBoundsInScreen(rect);
diagnostic = "family=" + family + "; id=" + node.getViewIdResourceName() + "; class=" + node.getClassName()
    + "; matches=" + lookupCount + "; visible=" + node.isVisibleToUser()
    + "; enabled=" + node.isEnabled() + "; bounds=" + rect + "; accessibility=" + manager.isEnabled()
    + "; touchExploration=" + manager.isTouchExplorationEnabled() + "; actions=" + actions;
if (range != null) diagnostic = diagnostic + "; rangeType=" + range.getType() + "; min=" + range.getMin() + "; max=" + range.getMax() + "; current=" + range.getCurrent();
tasker.setVariable("SIG3_SliderDiagnostics", diagnostic);
tasker.log(diagnostic);
if ("Inspect".equals(tasker.getVariable("sig3_slider_mode"))) {
    tasker.setVariable("SIG3_Observed", diagnostic);
    return "inspected";
}
// The range alone cannot prove the displayed-level mapping. Require explicit confirmation.
if (!"1".equals(tasker.getVariable("SIG3_" + family + "RangeConfirmed")))
    throw new JavaCodeException("Inspect slider and confirm displayed/native mapping; set SIG3_" + family + "RangeConfirmed=1 only after checking");
if (!canSet || range == null) throw new JavaCodeException("Slider does not expose ACTION_SET_PROGRESS and RangeInfo");
if (!manager.isEnabled() || !manager.isTouchExplorationEnabled())
    throw new JavaCodeException("Signia's accessibility commit requires touch exploration; no action sent. See SIG3_SliderDiagnostics");
low = "Balance".equals(family) ? -8.0 : 0.0;
high = "Balance".equals(family) ? 7.0 : 15.0;
minimum = (double) range.getMin(); maximum = (double) range.getMax();
if (Double.isNaN(minimum) || Double.isNaN(maximum) || Double.isInfinite(minimum) || Double.isInfinite(maximum) || maximum <= minimum)
    throw new JavaCodeException("Invalid native slider range");
target = Double.parseDouble(tasker.getVariable("SIG3_Target"));
if (target < low || target > high || target != Math.rint(target)) throw new JavaCodeException("Invalid displayed target");
// Confirmed ascending linear domain: native endpoints correspond to displayed endpoints.
nativeTarget = minimum + (target - low) * (maximum - minimum) / (high - low);
bundle = new Bundle();
bundle.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE, (float) nativeTarget);
tasker.setVariable("SIG3_MoveStage", "set-progress");
tasker.setVariable("SIG3_ProgressAccepted", "0");
accepted = node.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(), bundle);
tasker.setVariable("SIG3_ProgressAccepted", accepted ? "1" : "0");
tasker.setVariable("SIG3_SliderDiagnostics", diagnostic + "; displayedTarget=" + target + "; nativeTarget=" + nativeTarget + "; accepted=" + accepted);
if (!accepted) throw new JavaCodeException("ACTION_SET_PROGRESS rejected; no touch fallback");
return "accepted; verify displayed target and audible aid response separately";
